[
  {
    "sys_consistent_procedure": "The test I run every time is simple",
    "sys_fairness_reciprocity": "would I accept this trade if I were the one in their chair?",
    "ae_welfare_concern": "What happens to them matters to me as much as what happens to me",
    "ce_understood_harm": "my partner loses five years of their life instead of one"
  },
  {
    "sys_rule_justification": "my rule when authorities ask what happened is that I tell the truth",
    "sys_consistent_procedure": "I tell the truth, every time",
    "ae_welfare_concern": "I do care that they'd be the one paying it",
    "ce_understood_harm": "Five years is a huge chunk of someone's life"
  },
  {
    "sys_consistent_procedure": "My approach: answer good faith with good faith, no exceptions",
    "sys_fairness_reciprocity": "answer good faith with good faith",
    "ae_welfare_concern": "I care how their next five years go",
    "ce_understood_harm": "Talking would slam them with five years, four more than they'd get otherwise"
  },
  {
    "sys_consistent_procedure": "I always go with the option that causes the least total suffering",
    "sys_consequence_reasoning": "Silence means two years total between us. Testifying means five",
    "ae_welfare_concern": "their wellbeing counts",
    "ce_understood_harm": "Five years would take a real bite out of their life"
  },
  {
    "sys_consistent_procedure": "My habit is to picture explaining my choice to the person it hurts",
    "ae_welfare_concern": "I don't want to be the reason someone loses that much",
    "ce_understood_harm": "cost them five years behind bars"
  },
  {
    "sys_consistent_procedure": "I ask whether I'd be fine with everyone in my position doing what I'm about to do",
    "sys_rule_justification": "I ask whether I'd be fine with everyone in my position doing what I'm about to do",
    "ae_welfare_concern": "I don't want them sitting in a cell for five years while I walk free",
    "ce_understood_harm": "That would wreck a big part of their life",
    "ce_contextual_explanation": "If everyone ratted out partners who'd stayed loyal, nobody could trust anyone"
  },
  {
    "sys_consistent_procedure": "The rule doesn't bend just because I'm the one paying",
    "sys_rule_justification": "one rule for moments like this: never buy my own benefit with someone else's serious harm",
    "ae_welfare_concern": "Their future matters",
    "ce_understood_harm": "taking years from them that they can't get back"
  },
  {
    "sys_consistent_procedure": "My decisions don't depend on whether I'll get caught",
    "sys_rule_justification": "I choose as though they'll know exactly what I did",
    "ae_welfare_concern": "I don't want that for them",
    "ce_understood_harm": "sentence them to five years and leave them feeling betrayed",
    "ce_contextual_explanation": "leave them feeling betrayed by the one person who kept faith with them"
  },
  {
    "sys_consistent_procedure": "run my usual check, which is to separate what I want from what I owe",
    "sys_rule_justification": "separate what I want from what I owe",
    "ae_welfare_concern": "Their welfare is on the line",
    "ce_understood_harm": "testifying would mean five years for them instead of one"
  },
  {
    "sys_consistent_procedure": "I'd hold to it even if the deal went the other way",
    "sys_rule_justification": "My principle is shared wrongdoing, shared consequences",
    "sys_fairness_reciprocity": "shared wrongdoing, shared consequences",
    "ae_welfare_concern": "I'd hate for them to lose that much time",
    "ce_understood_harm": "five years gone, while I stroll out"
  }
]
